function apply(){
 for(const page of document.querySelectorAll('#pages > .page[data-page]')){
  const index=Number(page.dataset.page),layer=layers[index],g=geometry[index];
  if(!layer||!g)continue;
  const background=page.querySelector('img.background');
  if(!background)continue;
  if(!page.querySelector('.bpf-legal-f-screen')){
  const image=document.createElement('img');
  image.className='bpf-legal-f-screen';image.alt='';image.setAttribute('aria-hidden','true');
  Object.assign(image.style,{position:'absolute',left:layer.left+'%',top:layer.top+'%',width:layer.width+'%',height:layer.height+'%',pointerEvents:'none',userSelect:'none'});
  image.src=layer.src;
  background.after(image);
  }
  // Shift only the original F controls, retaining their events and identifiers.
  for(const cell of page.querySelectorAll('.bpf-item-code')){
   const code=cell.querySelector('.bpf-f')?.dataset.code||cell.querySelector('span')?.textContent?.trim();
   const row=g.rows.find(r=>r.code===code);if(!row)continue;
   Object.assign(cell.style,{top:(100*row.top/g.height)+'%',height:(100*(row.bottom-row.top)/g.height)+'%'});
  }
  if(g.obs?.name){
   const o=g.obs;
   for(const el of page.querySelectorAll('[data-field]'))if(el.dataset.field===o.name){
    el.style.top=(100*o.top/g.height)+'%';el.style.height=(100*(o.bottom-o.top)/g.height)+'%';
    if(typeof bpfFitProcessObservation==='function'&&el.matches('textarea'))bpfFitProcessObservation(el);
   }
   if(typeof D!=='undefined')for(const widget of D.widgets)if(widget.name===o.name&&widget.page===index)widget.rect[3]=widget.size[1]-o.top;
  }
 }
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply,{once:true});
else apply();
const host=document.getElementById('pages');
if(host)new MutationObserver(apply).observe(host,{childList:true});
